-- Hosbah: one server-level firewall rule (MH-580 J1), rendered by the agent's firewall.apply into a
-- dedicated `table inet hosbah` nftables table. Rules never touch any other nft table on the box.
-- The agent's own safety net (always allow the detected SSH port and established/related traffic,
-- keep the agent's outbound websocket alive) lives in the rendering code, not here: this table only
-- holds what the team asked for.
ALTER TABLE firewall_rules ADD CONSTRAINT firewall_rules_action_check CHECK (action IN ('allow', 'deny'));
ALTER TABLE firewall_rules ADD CONSTRAINT firewall_rules_proto_check CHECK (proto IN ('tcp', 'udp', 'any'));
ALTER TABLE firewall_rules ADD CONSTRAINT firewall_rules_port_check CHECK (
    port_start >= 1 AND port_start <= 65535 AND port_end >= port_start AND port_end <= 65535);
ALTER TABLE firewall_rules ADD CONSTRAINT firewall_rules_comment_check CHECK (length(comment) <= 200);
CREATE INDEX firewall_rules_server_idx ON firewall_rules (server_id, position);
CREATE INDEX firewall_rules_team_idx ON firewall_rules (team_id);
